// Pre-rendered Unreal technique clips. Unreal rendered each one to a video file;
// the page only plays the file. Nothing here starts a stream or selects the
// combat renderer. The clip list is generated by tools/import_unreal_clips.py.
import clips from './techniqueClips.data.js';

export const UNREAL_CLIPS = clips;

// The order the camera buttons appear in. Side is what opens first.
export const UNREAL_CLIP_CAMERAS = Object.freeze(['side', 'front']);

// Every clip so far was rendered with the same fixed outfits, whatever the
// player's own fighter wears. The page says so beside the picture.
export const UNREAL_CLIP_LOOK = Object.freeze({
  fighter: Object.freeze({ gi: 'white', swatch: '#eceef0' }),
  opponent: Object.freeze({ gi: 'navy', swatch: '#24376b' }),
  belt: 'black',
});

export function findUnrealClip(moveId, performerSide = 'fighter', camera = UNREAL_CLIP_CAMERAS[0]) {
  return clips.find((clip) => clip.moveId === moveId && clip.performerSide === performerSide && clip.camera === camera) ?? null;
}

// The camera views that exist for one move and performer, in button order.
export function unrealClipViews(moveId, performerSide = 'fighter') {
  return UNREAL_CLIP_CAMERAS.map((camera) => findUnrealClip(moveId, performerSide, camera)).filter(Boolean);
}
